#include <config.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "htslib/hfile.h"
#include "htslib/hts.h"
#include "htslib/sam.h"
#include "htslib/vcf.h"

static void hts_close_or_abort(htsFile* file) {
    if (hts_close(file) != 0) {
        abort();
    }
}

static void view_sam(htsFile *in) {
    if (!in) return;
    samFile *out = sam_open("/dev/null", "w");
    if (!out) abort();
    sam_hdr_t *hdr = sam_hdr_read(in);
    if (hdr == NULL) { hts_close_or_abort(out); return; }
    (void) sam_hdr_count_lines(hdr, "SQ");
    if (sam_hdr_write(out, hdr) != 0) {
        sam_hdr_destroy(hdr);
        hts_close_or_abort(out);
        return;
    }
    bam1_t *b = bam_init1();
    if (b == NULL) { sam_hdr_destroy(hdr); hts_close_or_abort(out); return; }
    while (sam_read1(in, hdr, b) >= 0) {
        if (sam_write1(out, hdr, b) < 0) break;
    }
    bam_destroy1(b);
    sam_hdr_destroy(hdr);
    hts_close_or_abort(out);
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *copy = malloc(sz);
    if (!copy) return 1;
    if (fread(copy, 1, sz, f) != (size_t)sz) return 1;
    fclose(f);
    hFILE *memfile = hopen("mem:", "rb:", copy, sz);
    if (memfile == NULL) { free(copy); return 0; }
    htsFile *ht_file = hts_hopen(memfile, "data", "rb");
    if (ht_file == NULL) {
        if (hclose(memfile) != 0) abort();
        return 0;
    }
    if (ht_file->format.category == sequence_data) {
        view_sam(ht_file);
    }
    hts_close_or_abort(ht_file);
    return 0;
}
